//I wouldn't miss a chance to do birbs!!!

let tacke = [];
let cols = 10;
let rows = 14;

let cellw, cellh;

let x1, x2, y1, y2, z1, z2;
let noisex = 30;
let noisey = 20;
let rndx, rndy;
let positive, negative;

function setup() {
  createCanvas(windowWidth, windowHeight);


  //size of 4sided polygon
  cellw = width/(cols-2);
  cellh = cellw*0.7;
  t = cellw/8; //length of the tangent for 4 bezier curves head and bottom of the body

  positive = color(243, 238, 229);
  negative = color(171, 24, 18);
  strokeWeight(1.5);

  //initialize all tiles
  for (let i=0; i<cols; i++) {
    tacke[i] = [];
    for (let j=0; j<rows; j++) {
      tacke[i][j] = new Tile(i*cellw, j*cellh, i, j, cellw, cellh);
    }
  }

	//noise speed depends on size of tile
  noisex = cellw/10;
  noisey = cellw/10;

  //noise seed
  x1 = 0;
  y1 =4;
  z1 =20;
  x2 = 5;
  y2 = 3;
  z2 = 100;
}


function draw() {
  background(positive);

  //global noise for all points
  y1=4;
  y2 =3;
  for (let i=0; i<cols; i++) {
    x1 = 0;
    x2 = 5;
    for (let j=0; j<rows; j++) {
      tacke[i][j].move();
      y1+=0.12;
      y2+=0.09;
    }
    x1+=0.009;
    x2+=0.015;
  }
  z1+=0.008;
  z2+=0.005;

  //display every second field, like chess fields
  for (let i=0; i<cols-1; i++) {
    for (let j=0; j<rows-1; j++) {
      if ((i%2 + j%2)%2 == 0) {
        tacke[i][j].display();
      }
    }
  }
}
